import time, random

def greedy_mis(n, edges, seed=0, mode=0, iterations=1000):
 adj=[set() for _ in range(n)]
 for u,v in edges: adj[u].add(v);adj[v].add(u)
 best=[]; rng=random.Random(seed)
 for _ in range(iterations):
  alive=set(range(n)); S=[]
  while alive:
   if mode==0:
    v=min(alive,key=lambda x:(len(adj[x]&alive),rng.random()))
   elif mode==1:
    v=max(alive,key=lambda x:(rng.random()/(len(adj[x]&alive)+.1)))
   elif mode==2:
    # randomized degree rank
    v=min(alive,key=lambda x:(len(adj[x]&alive)*rng.uniform(.65,1.35),rng.random()))
   S.append(v); alive.difference_update(adj[v]); alive.remove(v)
  if len(S)>len(best):best=S
 return best
