 while 1:
  outs=[]
  for v in range(n):
   if v not in S:
    ns=adj[v]&S
    if len(ns)==1: outs.append((v,next(iter(ns))))
  # group by removed u, candidates pair nonadjacent
  groups={}
  for v,u in outs:groups.setdefault(u,[]).append(v)
