import random,time,itertools

def greedy(n,adj,rng):
 alive=(1<<n)-1; S=[]
 while alive:
  vs=[]; x=alive
  while x:
   b=x&-x;v=b.bit_length()-1; x-=b
   # score random perturbed degree in current alive
   d=(adj[v]&alive).bit_count(); vs.append((d*rng.uniform(.65,1.35),rng.random(),v))
  v=min(vs)[2]; S.append(v); alive &= ~((1<<v)|adj[v])
 return S

def improve_k(n, adj,S,maxk=3):
 S=set(S)
 while True:
  # mask of neighbors in S for outside; active set list
  sl=list(S); idx={v:i for i,v in enumerate(sl)}
  out=[]; masks={}
  for v in range(n):
   if v not in S:
    m=0
    for u in adj[v]&S:m|=1<<idx[u]
    out.append(v);masks[v]=m
  change=None
  # k removal from 1 to maxk; only outside with mask subset removed set
  for k in range(1,min(maxk,len(S))+1):
   for remidx in itertools.combinations(range(len(sl)),k):
    rm=0
    for i in remidx:rm|=1<<i
    cands=[v for v in out if masks[v]&~rm==0]
    need=k+1
    if len(cands)<need:continue
    # DFS independent set of need
    chosen=[]
    def dfs(pos, avail):
     nonlocal chosen
     if len(chosen)>=need:return True
     if len(chosen)+len(avail)<need:return False
     while avail:
      v=avail[0]
      if dfs(0,[w for w in avail[1:] if w not in adj[v]]):
       chosen.append(v);return True
      avail=avail[1:]
      if len(chosen)+len(avail)<need:return False
     return False
    # implement combinations via recursive
    def find(start,cur):
     if len(cur)==need:return cur.copy()
     if len(cands)-start < need-len(cur):return None
     for j in range(start,len(cands)):
      v=cands[j]
      if all(w not in adj[v] for w in cur):
       z=find(j+1,cur+[v])
       if z:return z
     return None
    z=find(0,[])
    if z:
     change=(remidx,z);break
   if change:break
  if not change:break
  remidx,z=change
  for i in remidx:S.remove(sl[i])
  S.update(z)
 return list(S)

