def trial(n,adj,rng,mode):
 alive=(1<<n)-1; S=[]
 while alive:
  vs=[];x=alive
  while x:
   b=x&-x;v=b.bit_length()-1;x-=b;d=(adj[v]&alive).bit_count()
   if mode==0: score=d+rng.random()*2
   elif mode==1: score=d*rng.uniform(.4,1.6)
   elif mode==2: score=(d+0.1)**rng.uniform(.5,1.5)
   elif mode==3: score=d+ rng.expovariate(1)
   elif mode==4: score=rng.random()*(d+1)
   elif mode==5: score=d + (rng.random()-.5)*5
   elif mode==6: score=d*d*rng.uniform(.5,1.5)
   elif mode==7: score=d + 2*rng.random() + .15*len(adj[v].to_bytes((n+7)//8,'little'))
   vs.append((score,v))
  v=min(vs)[1];S.append(v);alive &= ~((1<<v)|adj[v])
 return S
