def walk(n,adj,S,rng,steps=500):
 S=set(S); best=set(S); taboo={}
 for it in range(steps):
  groups={};
  for v in range(n):
   if v not in S:
    x=adj[v]; ns=[]
    while x:
     b=x&-x;u=b.bit_length()-1;x-=b
     if u in S:ns.append(u)
     if len(ns)>1:break
    if len(ns)==1:groups.setdefault(ns[0],[]).append(v)
  # randomly choose improvement pair
  moves=[]
  for u,vs in groups.items():
   for i,v in enumerate(vs):
    for w in vs[i+1:]:
     if not (adj[v]>>w&1):moves.append((u,v,w))
  if moves:
   u,v,w=rng.choice(moves);S.remove(u);S.add(v);S.add(w)
   if len(S)>len(best):best=set(S)
   continue
  # neutral swap
  neutral=[(u,v) for u,vs in groups.items() for v in vs if taboo.get(v,-1)<=it and taboo.get(u,-1)<=it]
  if not neutral:break
  u,v=rng.choice(neutral)
  S.remove(u);S.add(v);taboo[u]=it+5;taboo[v]=it+5
 return best
