import time

def maxclique(n,edges,limit=1.0):
 G=[(1<<n)-1 ^ (1<<i) for i in range(n)]
 for u,v in edges:G[u]&=~(1<<v);G[v]&=~(1<<u) # complement excludes graph edges
 best=[]; nodes=0;start=time.process_time(); expired=False
 def color_sort(P):
  order=[]; bounds=[]; color=0; rem=P
  while rem:
   color+=1; avail=rem
   while avail:
    # choose max degree in current avail? 
    x=avail;v=-1;bd=-1
    while x:
     b=x&-x;u=b.bit_length()-1;x-=b
     d=(G[u]&avail).bit_count()
     if d>bd:bd=d;v=u
    bit=1<<v;order.append(v);bounds.append(color)
    rem &= ~bit;avail &= ~bit & ~G[v]
  return order,bounds
 def expand(P,R):
  nonlocal best,nodes,expired
  nodes+=1
  if nodes%10000==0 and time.process_time()-start>limit:expired=True;return
  if not P:
   if len(R)>len(best):best=R[:]
   return
  order,bounds=color_sort(P)
  for i in range(len(order)-1,-1,-1):
   if len(R)+bounds[i] <= len(best):return
   v=order[i];b=1<<v
   if P&b:
    Pn=P&G[v]
    if not Pn:
     if len(R)+1>len(best):best=R+[v]
    else:expand(Pn,R+[v])
    P &= ~b
   if expired:return
 expand((1<<n)-1,[])
 return len(best),nodes,time.process_time()-start,expired
